     "title": "伊朗军方警告：将袭击科威特及巴林港口油轮 船员需立即撤离",
     "url": "http://finance.eastmoney.com/news/1351,202609093868453569.html",
     "time": "09-09 04:09",
     "ts": 1788898179,
     "summary": "△伊朗哈尔克岛（资料图） 当地时间8日晚，伊朗伊斯兰革命卫队就美军袭击伊朗油轮事件发出紧急警告。 革命卫队警告称，鉴于美军袭击伊朗多艘油轮的罪恶行径，伊朗警告所有停泊在科威特和巴林港口的油轮船员，由于这些港口收留了美军，因此无论油轮停泊在锚地还是港口，船员都应立即离开，因为其将成为袭击目标。 当地时间8日晚，总台记者自伊朗方面获悉，一艘伊朗油轮在距离哈尔克岛4英里处遭到美军导弹袭击。当地消息人士称，事件中无人伤亡，油轮船员正在撤离。相关部门正在调查有关事件的具体情况。（文章来",
